      `
export const version = ${ADAPTER_CONTRACT_VERSION};
export const name = "fast-adp";
export const providers = ["prov-fast"];
export async function fetchData() {
  const probe = (globalThis.__pp120 ??= []);
  probe.push({ n: "B", t: Date.now(), k: "s" });
